package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PasswordRecoveryEnabledVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property password recovery enabled of tenant config ")
  void test_password_recovery_enabled_v_o_builder() {
    Assertions.assertFalse(PasswordRecoveryEnabledVO.nullValue().isPasswordRecoveryEnabled(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PasswordRecoveryEnabledVO.tryFrom(null).isPasswordRecoveryEnabled(),
        "With a null value, no present result");
    Assertions.assertEquals(true, PasswordRecoveryEnabledVO.from(true).isPasswordRecoveryEnabled());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> PasswordRecoveryEnabledVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", PasswordRecoveryEnabledVO.from(true).toString());
  }
}
